/* riscv64_memit.c — riscv64 machine-layer assembly emission (MIR-native).
 *
 * Emits the lowered MMOP machine IR as riscv64 (LP64D) assembly.  The
 * riscv64 ISA has no condition flags: comparisons are register-based
 * (MMOP_SETCCR → slt/sltu/...), branches compare registers directly
 * (the JCC terminator carries src[0]/src[1]), and there is no conditional
 * move (MMOP_CMOV is never generated by the riscv64 isel).
 *
 * Value operands are always materialized into the scratch registers t0/t1
 * before use (riscv has no memory/immediate operands for most ALU ops),
 * matching the x86 emitter's rax/rcx routing.
 *
 * Frame: the prologue saves fp/ra/s-regs above the spill+alloca slots,
 * so every slot is addressed `off(fp)` with off = v->slot - 16 (the 16
 * bytes of the fp+ra save area that the regalloc's savesz does not cover).
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "mir.h"
#include "riscv64_m.h"

static const MTargetM *g_mt;
static MFnM *g_fm;
static int g_alloca_cur;   /* frame-relative cursor for static allocas */
static const char *g_fname;
static int g_slot_base;    /* -16: fp+ra save area above the slots */

/* ---- width helpers ------------------------------------------------------ */

static int
alloca_size(MMOP op)
{
	switch (op) {
	case MMOP_ALLOCA4:  return 4;
	case MMOP_ALLOCA8:  return 8;
	default:            return 16;
	}
}

static int
alloca_size_ins(const MInsM *in)
{
	if (in->cst && in->cst->kind == MC_INT)
		return (int)in->cst->u.i;
	return alloca_size(in->op);
}

static int
alloca_total(MFnM *fm)
{
	int t = 0;
	for (MBlkM *b = fm->link; b; b = b->link)
		for (uint32_t i = 0; i < b->nins; i++) {
			MMOP op = b->ins[i].op;
			if (op == MMOP_ALLOCA4 || op == MMOP_ALLOCA8 ||
			    op == MMOP_ALLOCA16)
				t += alloca_size_ins(&b->ins[i]);
		}
	return t;
}

/* ---- value printing ------------------------------------------------------ */

static void
emit_const(FILE *f, MConst *c)
{
	if (!c) {
		fputs("0", f);
		return;
	}
	switch (c->kind) {
	case MC_INT:  fprintf(f, "%lld", (long long)c->u.i); break;
	case MC_FLT:  fprintf(f, "0x%x", c->u.s); break;
	case MC_ADDR: fprintf(f, "%s", c->u.addr.sym ? c->u.addr.sym : "0"); break;
	default:      fputs("0", f); break;
	}
}

/* Print a register, or a slot as fp-relative memory (only valid as a
 * load/store operand). */
static void
emit_mval(FILE *f, MVal *v)
{
	if (!v) {
		fputs("zero", f);
		return;
	}
	switch (v->kind) {
	case MV_REG:
		fprintf(f, "%s", mreg_name(g_mt, v->reg));
		break;
	case MV_TEMP:
		if (v->reg >= 0)
			fprintf(f, "%s", mreg_name(g_mt, v->reg));
		else
			fprintf(f, "%d(fp)", v->slot + g_slot_base);
		break;
	case MV_CONST:
		emit_const(f, v->con);
		break;
	case MV_GLOBAL:
		fprintf(f, "%s", v->sym ? v->sym : "0");
		break;
	default:
		fputs("zero", f);
		break;
	}
}

/* Load a value into a scratch register (handles immediates, slots).
 * rn is "t0"/"t1". */
static void
mv_to_scratch(FILE *f, MVal *v, const char *rn)
{
	if (!v) {
		fprintf(f, "\tmv\t%s, zero\n", rn);
		return;
	}
	switch (v->kind) {
	case MV_CONST: {
		int64_t c = v->con ? v->con->u.i : 0;
		if (c >= -2048 && c <= 2047)
			fprintf(f, "\tli\t%s, %lld\n", rn, (long long)c);
		else
			fprintf(f, "\tli\t%s, %lld\n\tsext.w\t%s, %s\n",
			        rn, (long long)c, rn, rn);
		break;
	}
	case MV_TEMP:
		if (v->reg >= 0)
			fprintf(f, "\tmv\t%s, %s\n", rn, mreg_name(g_mt, v->reg));
		else
			fprintf(f, "\tld\t%s, %d(fp)\n",
			        rn, v->slot + g_slot_base);
		break;
	case MV_REG:
		fprintf(f, "\tmv\t%s, %s\n", rn, mreg_name(g_mt, v->reg));
		break;
	case MV_GLOBAL:
		fprintf(f, "\tlui\t%s, %%pcrel_hi(%s)\n"
		            "\taddi\t%s, %s, %%pcrel_lo(%s)\n",
		        rn, v->sym ? v->sym : "0", rn, rn, v->sym ? v->sym : "0");
		break;
	default:
		fprintf(f, "\tmv\t%s, zero\n", rn);
		break;
	}
}

/* Write a scratch register back into the destination value. */
static void
scratch_to_dst(FILE *f, MVal *d, const char *rn)
{
	if (!d)
		return;
	switch (d->kind) {
	case MV_TEMP:
		if (d->reg >= 0)
			fprintf(f, "\tmv\t%s, %s\n", mreg_name(g_mt, d->reg), rn);
		else
			fprintf(f, "\tsd\t%s, %d(fp)\n", rn, d->slot + g_slot_base);
		break;
	case MV_REG:
		fprintf(f, "\tmv\t%s, %s\n", mreg_name(g_mt, d->reg), rn);
		break;
	default:
		break;
	}
}

/* ---- floating point ------------------------------------------------------ */

static const char *
fp_sfx(MType t)
{
	return t == MT_F32 ? "s" : "d";
}

/* Load a float value into a scratch FPR (f28/f29). */
static void
fmv_to_scratch(FILE *f, MVal *v, const char *rn)
{
	if (!v) {
		fprintf(f, "\tfcvt.%s.w\t%s, zero\n", fp_sfx(MT_F64), rn);
		return;
	}
	switch (v->kind) {
	case MV_CONST:
		if (v->con && v->con->kind == MC_FLT) {
			if (v->con->type == MT_F32) {
				uint32_t bits;
				memcpy(&bits, &v->con->u.s, 4);
				fprintf(f, "\tli\tt0, 0x%x\n", bits);
				fprintf(f, "\tfmv.w.x\t%s, t0\n", rn);
			} else {
				uint64_t bits;
				memcpy(&bits, &v->con->u.d, 8);
				fprintf(f, "\tli\tt0, 0x%llx\n",
				        (unsigned long long)bits);
				fprintf(f, "\tfmv.d.x\t%s, t0\n", rn);
			}
			return;
		}
		/* integer constant used as float: convert (rare) */
		fprintf(f, "\tli\tt0, %lld\n", (long long)v->con->u.i);
		fprintf(f, "\tfcvt.%s.w\t%s, t0\n",
		        fp_sfx(v->con->type == MT_F64 ? MT_F64 : MT_F32), rn);
		return;
	case MV_TEMP:
		if (v->reg >= 0)
			fprintf(f, "\tfmv.%s\t%s, %s\n",
			        fp_sfx(v->type), rn, mreg_name(g_mt, v->reg));
		else
			fprintf(f, "\tf%s\t%s, %d(fp)\n",
			        v->type == MT_F32 ? "lw" : "ld", rn,
			        v->slot + g_slot_base);
		return;
	case MV_REG:
		fprintf(f, "\tfmv.%s\t%s, %s\n",
		        fp_sfx(v->type), rn, mreg_name(g_mt, v->reg));
		return;
	default:
		fprintf(f, "\tfcvt.%s.w\t%s, zero\n", fp_sfx(MT_F64), rn);
		return;
	}
}

/* Write a scratch FPR back into the destination float value. */
static void
scratch_to_dst_f(FILE *f, MVal *d, const char *rn)
{
	if (!d)
		return;
	switch (d->kind) {
	case MV_TEMP:
		if (d->reg >= 0)
			fprintf(f, "\tfmv.%s\t%s, %s\n",
			        fp_sfx(d->type), mreg_name(g_mt, d->reg), rn);
		else
			fprintf(f, "\tf%s\t%s, %d(fp)\n",
			        d->type == MT_F32 ? "sw" : "sd", rn,
			        d->slot + g_slot_base);
		break;
	case MV_REG:
		fprintf(f, "\tfmv.%s\t%s, %s\n",
		        fp_sfx(d->type), mreg_name(g_mt, d->reg), rn);
		break;
	default:
		break;
	}
}

/* ---- load/store addressing ---------------------------------------------- */

/* Emit an address into the scratch register rn (t0/t1).  Symbolic targets
 * use the %pcrel_hi/lo pair. */
static void
emit_addr_to_scratch(FILE *f, MAddr a, const char *rn)
{
	MVal *base = a.base;
	if (a.offcon) {
		const char *sym = a.offcon->u.addr.sym;
		fprintf(f, "\tlui\t%s, %%pcrel_hi(%s)\n", rn, sym);
		fprintf(f, "\taddi\t%s, %s, %%pcrel_lo(%s)\n", rn, rn, sym);
		if (a.off)
			fprintf(f, "\taddi\t%s, %s, %lld\n", rn, rn, (long long)a.off);
		return;
	}
	if (base && base->kind == MV_TEMP && base->reg < 0) {
		/* base is a spill slot: address it off(fp) */
		fprintf(f, "\taddi\t%s, fp, %d\n", rn, base->slot + g_slot_base);
		if (a.off)
			fprintf(f, "\taddi\t%s, %s, %lld\n", rn, rn, (long long)a.off);
		return;
	}
	if (base && base->kind == MV_CONST) {
		fprintf(f, "\tli\t%s, %lld\n", rn, (long long)base->con->u.i);
		if (a.off)
			fprintf(f, "\taddi\t%s, %s, %lld\n", rn, rn, (long long)a.off);
		return;
	}
	if (base && base->kind == MV_GLOBAL) {
		/* address of a global symbol (e.g. an array) */
		const char *sym = base->sym ? base->sym : "0";
		fprintf(f, "\tlui\t%s, %%pcrel_hi(%s)\n", rn, sym);
		fprintf(f, "\taddi\t%s, %s, %%pcrel_lo(%s)\n", rn, rn, sym);
		if (a.off)
			fprintf(f, "\taddi\t%s, %s, %lld\n", rn, rn, (long long)a.off);
		return;
	}
	if (!base) {
		fprintf(f, "\tli\t%s, %lld\n", rn, (long long)a.off);
		return;
	}
	if (base->kind == MV_TEMP && base->reg < 0) {
		/* unreachable (handled above), keep for safety */
	}
	fprintf(f, "\taddi\t%s, ", rn);
	emit_mval(f, base);
	fprintf(f, ", %lld\n", (long long)a.off);
}

/* ---- condition suffix ---------------------------------------------------- */

static const char *
rv_cc_suffix(MCC cc)
{
	switch (cc) {
	case MCC_EQ:  return "eq";
	case MCC_NE:  return "ne";
	case MCC_GE:  return "ge";
	case MCC_LT:  return "lt";
	case MCC_GT:  return "gt";
	case MCC_LE:  return "le";
	case MCC_CS:  return "geu";
	case MCC_CC:  return "ltu";
	case MCC_HI:  return "gtu";
	case MCC_LS:  return "leu";
	default:      return "eq";
	}
}

/* dst = (src[0] cc src[1]) ? 1 : 0  (register comparison). */
static void
emit_setccr(FILE *f, MInsM *in)
{
	MVal *a = in->src[0];
	MVal *b = in->src[1];
	MCC cc = in->cc;
	if ((a && (a->type == MT_F32 || a->type == MT_F64)) ||
	    (b && (b->type == MT_F32 || b->type == MT_F64))) {
		/* floating-point comparison: flt/fle/feq write an INTEGER 0/1
		 * into rd (not an FPR), so the result lands directly in t0 */
		const char *sx = (a && a->type == MT_F32) ? "s" : "d";
		fmv_to_scratch(f, a, "f28");
		fmv_to_scratch(f, b, "f29");
		switch (cc) {
		case MCC_LT: fputs(sx[0]=='s'?"\tflt.s\tt0, f28, f29\n":"\tflt.d\tt0, f28, f29\n", f); break;
		case MCC_GT: fputs(sx[0]=='s'?"\tflt.s\tt0, f29, f28\n":"\tflt.d\tt0, f29, f28\n", f); break;
		case MCC_LE: fputs(sx[0]=='s'?"\tfle.s\tt0, f28, f29\n":"\tfle.d\tt0, f28, f29\n", f); break;
		case MCC_GE: fputs(sx[0]=='s'?"\tfle.s\tt0, f29, f28\n":"\tfle.d\tt0, f29, f28\n", f); break;
		case MCC_EQ: fputs(sx[0]=='s'?"\tfeq.s\tt0, f28, f29\n":"\tfeq.d\tt0, f28, f29\n", f); break;
		case MCC_NE: fputs(sx[0]=='s'?"\tfeq.s\tt0, f28, f29\n":"\tfeq.d\tt0, f28, f29\n", f);
		             fputs("\txori\tt0, t0, 1\n", f); break;
		default:     fputs(sx[0]=='s'?"\tflt.s\tt0, f28, f29\n":"\tflt.d\tt0, f28, f29\n", f); break;
		}
		fputs("\tsext.w\tt0, t0\n", f);   /* SETCCR yields an i32 bool */
		scratch_to_dst(f, in->dst, "t0");
		return;
	}
	mv_to_scratch(f, a, "t0");
	mv_to_scratch(f, b, "t1");
	switch (cc) {
	case MCC_LT:  fputs("\tslt\tt0, t0, t1\n", f); break;
	case MCC_GE:  fputs("\tslt\tt0, t0, t1\n\txori\tt0, t0, 1\n", f); break;
	case MCC_GT:  fputs("\tslt\tt0, t1, t0\n", f); break;
	case MCC_LE:  fputs("\tslt\tt0, t1, t0\n\txori\tt0, t0, 1\n", f); break;
	case MCC_CC:  fputs("\tsltu\tt0, t0, t1\n", f); break;
	case MCC_CS:  fputs("\tsltu\tt0, t0, t1\n\txori\tt0, t0, 1\n", f); break;
	case MCC_HI:  fputs("\tsltu\tt0, t1, t0\n", f); break;
	case MCC_LS:  fputs("\tsltu\tt0, t1, t0\n\txori\tt0, t0, 1\n", f); break;
	case MCC_EQ:  fputs("\tsub\tt0, t0, t1\n\tseqz\tt0, t0\n", f); break;
	case MCC_NE:  fputs("\tsub\tt0, t0, t1\n\tsnez\tt0, t0\n", f); break;
	default:      fputs("\tslt\tt0, t0, t1\n", f); break;
	}
	fputs("\tsext.w\tt0, t0\n", f);   /* SETCCR yields an i32 bool */
	scratch_to_dst(f, in->dst, "t0");
}

/* ---- binary op table ----------------------------------------------------- */

static const char *
binop_name(MMOP op)
{
	switch (op) {
	case MMOP_ADD:  return "add";
	case MMOP_SUB:  return "sub";
	case MMOP_MUL:  return "mul";
	case MMOP_AND:  return "and";
	case MMOP_OR:   return "or";
	case MMOP_XOR:  return "xor";
	case MMOP_SHL:  return "sll";
	case MMOP_SHR:  return "srl";
	case MMOP_SAR:  return "sra";
	case MMOP_DIV:  return "div";
	case MMOP_UDIV: return "divu";
	case MMOP_REM:  return "rem";
	case MMOP_UREM: return "remu";
	default:        return "add";
	}
}

static bool
binop_has_imm(MMOP op)
{
	return op == MMOP_ADD || op == MMOP_AND || op == MMOP_OR ||
	       op == MMOP_XOR || op == MMOP_SHL || op == MMOP_SHR ||
	       op == MMOP_SAR;
}

/* ---- main emission ------------------------------------------------------- */

/* Branch operand: return a register name; load slot/const values into a
 * scratch register first (riscv branches only take registers). */
static const char *
branch_src(FILE *f, MVal *v, const char *rn)
{
	if (!v)
		return "zero";
	if (v->kind == MV_REG)
		return mreg_name(g_mt, v->reg);
	if (v->kind == MV_TEMP && v->reg >= 0)
		return mreg_name(g_mt, v->reg);
	mv_to_scratch(f, v, rn);
	return rn;
}

static void
emit_ins(FILE *f, MInsM *in)
{
	MVal *d = in->dst;
	MVal *s0 = in->src[0];
	MVal *s1 = in->src[1];
	MMOP op = in->op;

	switch (op) {
	case MMOP_MOV:
		if (in->dtype == MT_F32 || in->dtype == MT_F64) {
			fmv_to_scratch(f, s0, "f28");
			scratch_to_dst_f(f, d, "f28");
			return;
		}
		mv_to_scratch(f, s0, "t0");
		scratch_to_dst(f, d, "t0");
		return;
	case MMOP_MOVSX:
		mv_to_scratch(f, s0, "t0");
		switch (in->dtype) {
		case MT_I8:  fputs("\tslli\tt0, t0, 56\n\tsrai\tt0, t0, 56\n", f); break;
		case MT_I16: fputs("\tslli\tt0, t0, 48\n\tsrai\tt0, t0, 48\n", f); break;
		case MT_I32: fputs("\tsext.w\tt0, t0\n", f); break;
		default:     break;
		}
		scratch_to_dst(f, d, "t0");
		return;
	case MMOP_MOVZX:
		mv_to_scratch(f, s0, "t0");
		switch (in->dtype) {
		case MT_I8:  fputs("\tandi\tt0, t0, 255\n", f); break;
		case MT_I16: fputs("\tslli\tt0, t0, 48\n\tsrli\tt0, t0, 48\n", f); break;
		case MT_I32: fputs("\tslli\tt0, t0, 32\n\tsrli\tt0, t0, 32\n", f); break;
		default:     break;
		}
		scratch_to_dst(f, d, "t0");
		return;
	case MMOP_LEA:
		emit_addr_to_scratch(f, in->addr, "t0");
		scratch_to_dst(f, d, "t0");
		return;
	case MMOP_ADD: case MMOP_SUB: case MMOP_MUL:
	case MMOP_AND: case MMOP_OR:  case MMOP_XOR:
	case MMOP_SHL: case MMOP_SHR: case MMOP_SAR:
	case MMOP_DIV: case MMOP_UDIV: case MMOP_REM: case MMOP_UREM: {
		const char *opn = binop_name(op);
		mv_to_scratch(f, s0, "t0");
		if (binop_has_imm(op) && s1 && s1->kind == MV_CONST) {
			int64_t v = s1->con->u.i;
			if (v >= -2048 && v <= 2047)
				fprintf(f, "\t%si\tt0, t0, %lld\n", opn, (long long)v);
			else {
				fprintf(f, "\tli\tt1, %lld\n", (long long)v);
				fprintf(f, "\t%s\tt0, t0, t1\n", opn);
			}
		} else {
			mv_to_scratch(f, s1, "t1");
			fprintf(f, "\t%s\tt0, t0, t1\n", opn);
		}
		scratch_to_dst(f, d, "t0");
		return;
	}
	case MMOP_NEG:
		mv_to_scratch(f, s0, "t0");
		fputs("\tsub\tt0, zero, t0\n", f);
		scratch_to_dst(f, d, "t0");
		return;
	case MMOP_NOT:
		mv_to_scratch(f, s0, "t0");
		fputs("\txori\tt0, t0, -1\n", f);
		scratch_to_dst(f, d, "t0");
		return;
	case MMOP_FADD: case MMOP_FSUB: case MMOP_FMUL: case MMOP_FDIV: {
		const char *opn = op == MMOP_FADD ? "fadd" :
		                  op == MMOP_FSUB ? "fsub" :
		                  op == MMOP_FMUL ? "fmul" : "fdiv";
		const char *sx = fp_sfx(in->dtype);
		fmv_to_scratch(f, s0, "f28");
		fmv_to_scratch(f, s1, "f29");
		fprintf(f, "\t%s.%s\tf28, f28, f29\n", opn, sx);
		scratch_to_dst_f(f, d, "f28");
		return;
	}
	case MMOP_FNEG:
		fmv_to_scratch(f, s0, "f28");
		fprintf(f, "\tfneg.%s\tf28, f28\n", fp_sfx(in->dtype));
		scratch_to_dst_f(f, d, "f28");
		return;
	case MMOP_FSQRT:
		fmv_to_scratch(f, s0, "f28");
		fprintf(f, "\tfsqrt.%s\tf28, f28\n", fp_sfx(in->dtype));
		scratch_to_dst_f(f, d, "f28");
		return;
	case MMOP_CVTSI2SS: case MMOP_CVTSI2SD:
	case MMOP_CVTSI2SS_U: case MMOP_CVTSI2SD_U: {
		/* int -> fp: source in GPR (width by its type), dst in f28 */
		const char *sx = (op == MMOP_CVTSI2SS || op == MMOP_CVTSI2SS_U)
		                 ? "s" : "d";
		bool uns = (op == MMOP_CVTSI2SS_U || op == MMOP_CVTSI2SD_U);
		const char *sw = "w";
		if (s0 && (s0->type == MT_I64 || s0->type == MT_PTR))
			sw = "l";
		mv_to_scratch(f, s0, "t0");
		fprintf(f, "\tfcvt.%s.%s%s\tf28, t0\n",
		        sx, sw, uns ? "u" : "");
		scratch_to_dst_f(f, d, "f28");
		return;
	}
	case MMOP_CVTTSS2SI: case MMOP_CVTTSD2SI: {
		/* fp -> int (round toward zero = C cast); dst in GPR.  The
		 * default rounding mode is RNE; an explicit `rtz` is required
		 * for C truncation semantics ((int)18.875 == 18). */
		const char *sx = op == MMOP_CVTTSS2SI ? "s" : "d";
		const char *dw = (d && (d->type == MT_I64 || d->type == MT_PTR))
		                 ? "l" : "w";
		fmv_to_scratch(f, s0, "f28");
		fprintf(f, "\tfcvt.%s.%s\tt0, f28, rtz\n", dw, sx);
		scratch_to_dst(f, d, "t0");
		return;
	}
	case MMOP_CVTSS2SD:
		fmv_to_scratch(f, s0, "f28");
		fputs("\tfcvt.d.s\tf28, f28\n", f);
		scratch_to_dst_f(f, d, "f28");
		return;
	case MMOP_CVTSD2SS:
		fmv_to_scratch(f, s0, "f28");
		fputs("\tfcvt.s.d\tf28, f28\n", f);
		scratch_to_dst_f(f, d, "f28");
		return;
	case MMOP_BLIT: {
		/* aggregate copy: src[1] -> src[0], cst bytes.  Unrolled 8-byte
		 * chunks with a byte remainder (sizes are struct smalls). */
		int64_t sz = in->cst ? in->cst->u.i : 0;
		if (sz <= 0)
			return;
		mv_to_scratch(f, s0, "t0");   /* dst pointer */
		mv_to_scratch(f, s1, "t1");   /* src pointer */
		int64_t n8 = sz / 8;
		for (int64_t i = 0; i < n8; i++) {
			fprintf(f, "\tld\tt2, %lld(t1)\n\tsd\tt2, %lld(t0)\n",
			        (long long)(i * 8), (long long)(i * 8));
		}
		for (int64_t i = n8 * 8; i < sz; i++)
			fprintf(f, "\tlb\tt2, %lld(t1)\n\tsb\tt2, %lld(t0)\n",
			        (long long)i, (long long)i);
		return;
	}
	case MMOP_SETCCR:
		emit_setccr(f, in);
		return;
	case MMOP_LOAD:
	case MMOP_LOAD_S8: case MMOP_LOAD_S16: case MMOP_LOAD_S32:
	case MMOP_LOAD_Z8: case MMOP_LOAD_Z16: case MMOP_LOAD_Z32: {
		if (in->dtype == MT_F32 || in->dtype == MT_F64) {
			/* floating-point load into the FPR scratch */
			const char *lw = in->dtype == MT_F32 ? "flw" : "fld";
			emit_addr_to_scratch(f, in->addr, "t0");
			fprintf(f, "\t%s\tf28, 0(t0)\n", lw);
			scratch_to_dst_f(f, d, "f28");
			return;
		}
		const char *lw = "ld";
		if (in->dtype == MT_I32)
			lw = "lw";
		switch (op) {
		case MMOP_LOAD_S8:  lw = "lb"; break;
		case MMOP_LOAD_S16: lw = "lh"; break;
		case MMOP_LOAD_S32: lw = "lw"; break;
		case MMOP_LOAD_Z8:  lw = "lbu"; break;
		case MMOP_LOAD_Z16: lw = "lhu"; break;
		case MMOP_LOAD_Z32: lw = "lwu"; break;
		default: break;
		}
		emit_addr_to_scratch(f, in->addr, "t0");
		fprintf(f, "\t%s\tt0, 0(t0)\n", lw);
		scratch_to_dst(f, d, "t0");
		return;
	}
	case MMOP_STORE: {
		if (in->dtype == MT_F32 || in->dtype == MT_F64) {
			const char *sw = in->dtype == MT_F32 ? "fsw" : "fsd";
			/* address in t1: fmv_to_scratch clobbers t0 when the value
			 * is a float constant (li bits), so keep the two apart */
			emit_addr_to_scratch(f, in->addr, "t1");
			fmv_to_scratch(f, s0, "f28");
			fprintf(f, "\t%s\tf28, 0(t1)\n", sw);
			return;
		}
		const char *sw = "sd";
		if (in->dtype == MT_I32)
			sw = "sw";
		emit_addr_to_scratch(f, in->addr, "t0");
		mv_to_scratch(f, s0, "t1");
		fprintf(f, "\t%s\tt1, 0(t0)\n", sw);
		return;
	}
	case MMOP_ALLOCA4: case MMOP_ALLOCA8: case MMOP_ALLOCA16: {
		if (s0 && s0->kind != MV_CONST) {
			mv_to_scratch(f, s0, "t0");
			fputs("\taddi\tt0, t0, 15\n\tandi\tt0, t0, -16\n"
			      "\tsub\tsp, sp, t0\n\tmv\tt0, sp\n", f);
			scratch_to_dst(f, d, "t0");
			if (g_fm)
				g_fm->dynalloc = true;
			return;
		}
		g_alloca_cur -= alloca_size_ins(in);
		/* g_alloca_cur is already a frame-relative fp offset (starts at
		 * -(fm->slot + 16 + csaves*8), frame reserves the alloca area
		 * below it); adding g_slot_base (-16) here pushed the alloca
		 * below sp (frame under-allocation; crashed float/struct-heavy
		 * functions at runtime). */
		fprintf(f, "\taddi\tt0, fp, %d\n", g_alloca_cur);
		scratch_to_dst(f, d, "t0");
		return;
	}
	case MMOP_SALLOC: {
		int64_t sz = in->cst ? in->cst->u.i : 0;
		fprintf(f, "\taddi\tsp, sp, -%lld\n", (long long)sz);
		return;
	}
	case MMOP_JMP:
		return;   /* handled by the block loop */
	case MMOP_JCC: {
		MVal *a = in->src[0];
		MVal *b = in->src[1];
		const char *sfx = rv_cc_suffix(in->cc);
		/* b == const 0: boolean branch (bnez/beqz on a) */
		if (b && b->kind == MV_CONST && b->con->u.i == 0) {
			const char *ra = branch_src(f, a, "t0");
			fprintf(f, "\t%s\t%s, .L%s.bb%u\n",
			        in->cc == MCC_NE ? "bnez" : "beqz", ra,
			        g_fname, in->blk->s1 ? in->blk->s1->id : 0);
			goto jcc_fall;
		}
		if (a && a->kind == MV_CONST && a->con->u.i == 0) {
			const char *rb = branch_src(f, b, "t0");
			fprintf(f, "\t%s\t%s, .L%s.bb%u\n",
			        in->cc == MCC_NE ? "beqz" : "bnez", rb,
			        g_fname, in->blk->s1 ? in->blk->s1->id : 0);
			goto jcc_fall;
		}
		{
			const char *ra = branch_src(f, a, "t0");
			const char *rb = branch_src(f, b, "t1");
			fprintf(f, "\tb%s\t%s, %s, .L%s.bb%u\n", sfx, ra, rb,
			        g_fname, in->blk->s1 ? in->blk->s1->id : 0);
		}
	jcc_fall:
		/* blocks are emitted in reverse link order, so the false target
		 * is never the physical next block — branch explicitly */
		if (in->blk->s2)
			fprintf(f, "\tj\t.L%s.bb%u\n", g_fname, in->blk->s2->id);
		return;
	}
	case MMOP_CALL: {
		if (s0 && s0->kind == MV_GLOBAL)
			fprintf(f, "\tcall\t%s\n", s0->sym ? s0->sym : "?");
		else if (s0) {
			mv_to_scratch(f, s0, "t0");
			fputs("\tjalr\tra, 0(t0)\n", f);
		}
		if (d) {
			if (d->type == MT_F32 || d->type == MT_F64)
				scratch_to_dst_f(f, d, "fa0");
			else
				scratch_to_dst(f, d, "a0");
		}
		return;
	}
	case MMOP_RET:
		return;   /* handled by the block loop */
	case MMOP_NOP:
		return;
	default:
		fprintf(f, "\t# unsupported MMOP %d\n", (int)op);
		return;
	}
}

static int csave_idx(const MTargetM *mt, int r);

static void
emit_block(FILE *f, MBlkM *b)
{
	fprintf(f, ".L%s.bb%u:\n", g_fname, b->id);
	for (uint32_t i = 0; i < b->nins; i++)
		emit_ins(f, &b->ins[i]);

	switch (b->term.op) {
	case MMOP_JMP:
		fprintf(f, "\tj\t.L%s.bb%u\n", g_fname, b->s1 ? b->s1->id : 0);
		break;
	case MMOP_JCC: {
		MInsM t = b->term;
		t.blk = b;
		emit_ins(f, &t);
		break;
	}
	case MMOP_RET: {
		MInsM t = b->term;
		t.blk = b;
		/* return value move: a0 (int) / fa0 (float) */
		if (t.src[0] && (t.src[0]->type == MT_F32 || t.src[0]->type == MT_F64)) {
			fmv_to_scratch(f, t.src[0], "fa0");
		} else if (t.src[0]) {
			mv_to_scratch(f, t.src[0], "a0");
		}
		/* restore callee-saved s-regs in save order */
		for (int i = 0; g_mt->rclob && g_mt->rclob[i] >= 0; i++)
			if ((g_fm->regsused >> g_mt->rclob[i]) & 1) {
				int off = -24 - 8 * csave_idx(g_mt, g_mt->rclob[i]);
				bool isf = g_mt->rclob[i] >= g_mt->fpr0;
				fprintf(f, "\t%s\t%s, %d(fp)\n",
				        isf ? "fld" : "ld",
				        mreg_name(g_mt, g_mt->rclob[i]), off);
			}
		fputs("\tld\tra, -8(fp)\n", f);
		fputs("\taddi\tsp, fp, 0\n", f);
		fputs("\tld\tfp, -16(sp)\n", f);
		fputs("\tret\n", f);
		break;
	}
	default:
		break;
	}
}

static int
csave_idx(const MTargetM *mt, int r)
{
	int idx = 0;
	for (int i = 0; mt->rclob && mt->rclob[i] >= 0; i++) {
		if (mt->rclob[i] == r)
			return idx;
		idx++;
	}
	return -1;
}

void
mfnm_emit_riscv64(MFnM *fm, FILE *f)
{
	g_mt = fm->mt;
	g_fm = fm;
	g_fname = fm->name ? fm->name : "?";
	g_slot_base = -16;      /* fp (8) + ra (8) save area above the slots */

	fm->dynalloc = false;
	for (MBlkM *b = fm->link; !fm->dynalloc && b; b = b->link)
		for (uint32_t i = 0; i < b->nins; i++) {
			MMOP op = b->ins[i].op;
			if ((op == MMOP_ALLOCA4 || op == MMOP_ALLOCA8 ||
			     op == MMOP_ALLOCA16) &&
			    b->ins[i].src[0] && b->ins[i].src[0]->kind != MV_CONST) {
				fm->dynalloc = true;
				break;
			}
		}

	int csaves = 0;
	for (int i = 0; fm->mt->rclob && fm->mt->rclob[i] >= 0; i++)
		if ((fm->regsused >> fm->mt->rclob[i]) & 1)
			csaves++;

	int framesize = fm->slot + 16 + csaves * 8 + alloca_total(fm);
	framesize = (framesize + 15) & ~15;
	g_alloca_cur = -(fm->slot + 16 + csaves * 8);

	fprintf(f, ".text\n");
	if (fm->name) {
		if (fm->host && fm->host->export)
			fprintf(f, ".globl %s\n", fm->name);
		fprintf(f, "%s:\n", fm->name);
	}
	fprintf(f, "\taddi\tsp, sp, -%d\n", framesize);
	fprintf(f, "\tsd\tra, %d(sp)\n", framesize - 8);
	fprintf(f, "\tsd\tfp, %d(sp)\n", framesize - 16);
	fprintf(f, "\taddi\tfp, sp, %d\n", framesize);
	for (int i = 0; fm->mt->rclob && fm->mt->rclob[i] >= 0; i++)
		if ((fm->regsused >> fm->mt->rclob[i]) & 1) {
			int off = -24 - 8 * csave_idx(fm->mt, fm->mt->rclob[i]);
			bool isf = fm->mt->rclob[i] >= fm->mt->fpr0;
			fprintf(f, "\t%s\t%s, %d(fp)\n",
			        isf ? "fsd" : "sd",
			        mreg_name(fm->mt, fm->mt->rclob[i]), off);
		}

	/* mfnm_addblk prepends, so fm->link is in REVERSE block order and the
	 * entry block sits at the tail.  Branch to the real entry block after
	 * the prologue (mirrors the x86_64 emitter); without this a multi-block
	 * function falls into the last block and its entry-block setup (alloca
	 * addresses etc.) never runs. */
	if (fm->start)
		fprintf(f, "\tj\t.L%s.bb%u\n", g_fname, fm->start->id);

	for (MBlkM *b = fm->link; b; b = b->link)
		emit_block(f, b);
}
